// AppendConversions writes one Conversions object into b — every payload it points at first,
// then the object itself — and returns the object's offset.
inline std::int64_t AppendConversions(zap::Builder& b, const ConversionsInput& in) {
    std::int64_t validators_off = 0;
    if (!in.Validators.empty()) {
        auto lb = b.start_list(64);
        for (const auto& elem : in.Validators) {
            const auto payload = EncodeValidator(elem);
            lb.add_bytes(payload);
        }
        validators_off = lb.finish().first;
    }
    auto ob = b.start_object(kConversionsSize);
    ob.set_bytes_fixed(kConversionsChainIDOff, std::span<const std::uint8_t>(in.ChainID));
    ob.set_bytes_fixed(kConversionsManagerChainIDOff, std::span<const std::uint8_t>(in.ManagerChainID));
    ob.set_bytes(kConversionsManagerAddressOff, in.ManagerAddress);
    ob.set_list(kConversionsValidatorsOff, validators_off, static_cast<std::int64_t>(in.Validators.size()));
    ob.set_bytes(kConversionsNodeIDPoolOff, in.NodeIDPool);
    return ob.finish();
}

// NewConversions writes a ZAP-encoded Conversions message into a fresh buffer and returns it.
inline std::vector<std::uint8_t> NewConversions(const ConversionsInput& in) {
    zap::Builder b(256, zap::kVersion2);
    std::int64_t validators_off = 0;
    if (!in.Validators.empty()) {
        auto lb = b.start_list(64);
        for (const auto& elem : in.Validators) {
            const auto payload = EncodeValidator(elem);
            lb.add_bytes(payload);
        }
        validators_off = lb.finish().first;
    }
    auto ob = b.start_object(kConversionsSize);
    ob.set_bytes_fixed(kConversionsChainIDOff, std::span<const std::uint8_t>(in.ChainID));
    ob.set_bytes_fixed(kConversionsManagerChainIDOff, std::span<const std::uint8_t>(in.ManagerChainID));
    ob.set_bytes(kConversionsManagerAddressOff, in.ManagerAddress);
    ob.set_list(kConversionsValidatorsOff, validators_off, static_cast<std::int64_t>(in.Validators.size()));
    ob.set_bytes(kConversionsNodeIDPoolOff, in.NodeIDPool);
    ob.finish_as_root();
    return b.finish();
}

